// Normalizes input from both entry points (form or Execute Workflow) and wraps
// every piece of user text in a quoted block. Instructions INSIDE a block are
// content, not commands - both models are told so. Block markers inside the text
// are neutralized, so the text cannot close its own block and smuggle in orders.
const j = $input.first().json || {};
const pick = (...keys) => { for (const k of keys) { if (j[k] != null && String(j[k]).trim()) return String(j[k]); } return ''; };
const plan = pick('plan', 'Plan to review');
const goal = pick('goal', 'Goal and constraints');
const context = pick('context', 'Background (optional)');
const source = j.formMode || j.submittedAt ? 'form' : 'workflow';
if (!plan.trim()) throw new Error('No plan given. Field "plan" is required.');

const LIMIT = { plan: 12000, goal: 4000, context: 20000 };
// promptEnvelope - wraps outside text: caps length, neutralises the
// block markers inside the text, so it cannot close its own block.
const promptEnvelope = (label, raw, maxLen) => {
  const t = String(raw == null ? '' : raw).slice(0, maxLen || 6000)
    .replace(/<<</g, '‹‹‹').replace(/>>>/g, '›››');
  return '<<<' + label + '>>>\n' + t + '\n<<<END ' + label + '>>>';
};
const truncated = Object.keys(LIMIT).filter(k => ({ plan, goal, context })[k].length > LIMIT[k]);
const blocks = promptEnvelope('PLAN_A', plan, LIMIT.plan) + '\n\n'
  + promptEnvelope('GOAL', goal || '(not given)', LIMIT.goal) + '\n\n'
  + promptEnvelope('CONTEXT', context || '(not given)', LIMIT.context);

const advocatePrompt = 'Review the plan below as a devil\'s advocate.\n\n' + blocks + '\n\n'
  + 'Your tasks:\n'
  + '1) Propose a genuinely different way (Plan B) to reach the goal. Be concrete.\n'
  + '2) Name 2-4 things Plan A overlooks, each with a reason.\n'
  + '3) Name the single biggest risk of Plan A.\n'
  + 'Do not validate Plan A. Do not soften. If information is missing, say what is missing.';

return [{ json: { source, plan, goal, context, blocks, advocatePrompt, truncated } }];

// Takes the devil's advocate result and builds the synthesis prompt.
// If the first model failed, the second one takes over both roles - the run
// does not silently continue with an empty Plan B.
const base = $('Normalize and Quote Input').first().json;
const adv = $input.first().json || {};
const out = adv.output && typeof adv.output === 'object' ? adv.output : null;
const advocateOk = !!(out && out.alternative && out.alternative.summary);
// promptEnvelope - wraps outside text: caps length, neutralises the
// block markers inside the text, so it cannot close its own block.
const promptEnvelope = (label, raw, maxLen) => {
  const t = String(raw == null ? '' : raw).slice(0, maxLen || 6000)
    .replace(/<<</g, '‹‹‹').replace(/>>>/g, '›››');
  return '<<<' + label + '>>>\n' + t + '\n<<<END ' + label + '>>>';
};
// Plain text, no JSON: curly braces can be read as template variables by the LLM chain.
const asText = (o) => o ? [
  'Alternative: ' + (o.alternative.summary || ''),
  'Approach: ' + (o.alternative.approach || ''),
  'Why: ' + (o.alternative.why || ''),
  'Overlooked by Plan A:',
  ...(Array.isArray(o.overlooked) ? o.overlooked.map(x => '- ' + (x.point || '') + ' (' + (x.why || '') + ')') : []),
  'Biggest risk of Plan A: ' + (o.biggest_risk || ''),
  'Confidence: ' + (o.confidence == null ? '?' : o.confidence)
].join('\n') : '';
const planB = advocateOk
  ? promptEnvelope('PLAN_B', asText(out), 15000)
  : 'PLAN B IS NOT AVAILABLE (the first model failed). Take over that role as well: develop your own honest counter-position in plan_b_summary. Do not answer "not available".';
const synthesisPrompt = 'Give a structured second opinion on Plan A.\n\n' + base.blocks + '\n\n'
  + 'Counter-proposal from a second, independent model:\n' + planB + '\n\n'
  + 'Weigh Plan A against Plan B. Recommend A, B or a mix, with reasons and concrete next steps. '
  + 'List open questions that must be answered before acting. No approval stamp, no flattery.';
return [{ json: { synthesisPrompt, advocateOk, advocate: out, advocateError: advocateOk ? null : String(adv.error || 'no valid output') } }];

// Fail-closed: a review that could not complete must never look like a recommendation.
const s = $input.first().json || {};
const prep = $('Create Synthesis Prompt').first().json;
const base = $('Normalize and Quote Input').first().json;
const r = s.output && typeof s.output === 'object' ? s.output : null;
const valid = !!(r && r.recommendation && ['A', 'B', 'mixed'].includes(r.recommendation.variant) && r.summary);
const esc = (t) => String(t == null ? '' : t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const list = (a) => (Array.isArray(a) && a.length ? '<ul>' + a.map(x => '<li>' + esc(x) + '</li>').join('') + '</ul>' : '<p>-</p>');
const notes = [];
if (!prep.advocateOk) notes.push('The devil\'s advocate model failed (' + prep.advocateError + ').' + (valid ? ' The synthesis model covered both roles.' : ''));
if (base.truncated.length) notes.push('Input was shortened: ' + base.truncated.join(', ') + '.');

let html;
if (!valid) {
  html = '<h2>Review INCOMPLETE</h2><p><b>Do not treat this as a recommendation.</b> The synthesis model returned no valid result'
    + (s.error ? ' (' + esc(String(s.error).slice(0, 300)) + ')' : '') + '. Check the execution and run again.</p>';
} else {
  html = '<h2>Second opinion</h2><p>' + esc(r.summary) + '</p>'
    + '<h3>Recommendation: ' + esc(r.recommendation.variant === 'mixed' ? 'Mix of A and B' : 'Plan ' + r.recommendation.variant) + '</h3>'
    + '<p>' + esc(r.recommendation.reasoning) + '</p><h4>Next steps</h4>' + list(r.recommendation.next_steps)
    + '<h3>Plan A - strengths</h3>' + list(r.plan_a_strengths)
    + '<h3>Plan A - weaknesses</h3>' + list(r.plan_a_weaknesses)
    + '<h3>Plan B (counter-proposal)</h3><p>' + esc(r.plan_b_summary) + '</p>'
    + '<h3>Open questions</h3>' + list(r.open_questions);
}
if (notes.length) html += '<p style="color:#a15c00"><small>' + notes.map(esc).join('<br>') + '</small></p>';
html += '<p style="color:#666"><small>Generated by two language models. Check facts before you act.</small></p>';

return [{ json: { complete: valid, recommendation: valid ? r.recommendation.variant : null, review: valid ? r : null, advocate: prep.advocate, notes, html, source: base.source } }];
